/** 24 小时制世界时钟：/世界/时间 须为 HH:mm，禁止「黄昏」等抽象时段 */

const CLOCK_RE = /^(\d{1,2}):(\d{2})$/;

const ABSTRACT_TIME_MAP: [RegExp, string][] = [
  [/凌晨|子夜|深夜|半夜/, '00:30'],
  [/黎明/, '05:30'],
  [/清晨|早晨|早上/, '06:30'],
  [/上午/, '09:00'],
  [/正午|中午/, '12:00'],
  [/下午/, '15:00'],
  [/黄昏|傍晚/, '18:00'],
  [/入夜|夜晚|夜间|夜里/, '20:00'],
];

export function parseWorldClock(time: string): { hour: number; minute: number } | null {
  const trimmed = time.trim();
  const match = trimmed.match(CLOCK_RE);
  if (!match) {
    return null;
  }
  const hour = Number(match[1]);
  const minute = Number(match[2]);
  if (hour < 0 || hour > 23 || minute < 0 || minute > 59) {
    return null;
  }
  return { hour, minute };
}

export function formatWorldClock(hour: number, minute: number): string {
  return `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
}

/** 将旧存档抽象时段或 HH:mm 统一为 HH:mm */
export function normalizeWorldTime(raw: string, fallback = '18:00'): string {
  const text = String(raw ?? '').trim();
  if (!text) {
    return fallback;
  }
  const parsed = parseWorldClock(text);
  if (parsed) {
    return formatWorldClock(parsed.hour, parsed.minute);
  }
  for (const [pattern, clock] of ABSTRACT_TIME_MAP) {
    if (pattern.test(text)) {
      return clock;
    }
  }
  return fallback;
}

export function minutesSinceMidnight(time: string): number {
  const normalized = normalizeWorldTime(time);
  const parsed = parseWorldClock(normalized);
  if (!parsed) {
    return 18 * 60;
  }
  return parsed.hour * 60 + parsed.minute;
}

/** 据前后时钟与跨日差估算流逝小时数（供工作队列/探索编队 tick） */
export function estimateElapsedHours(prevTime: string, currTime: string, dayDelta: number): number {
  const prevMin = minutesSinceMidnight(prevTime);
  let currMin = minutesSinceMidnight(currTime) + dayDelta * 24 * 60;
  if (dayDelta === 0 && currMin < prevMin) {
    currMin += 24 * 60;
  }
  const deltaMinutes = currMin - prevMin;
  if (deltaMinutes <= 0) {
    return 0;
  }
  return deltaMinutes / 60;
}

const EVENING_CUTOFF_MINUTES = 18 * 60;

/**
 * 外出默认计划时长：默认 8h，若距当日 18:00 不足 8h 则取剩余时长，最少 2h（schema 上限 8）。
 * 当前已在 18:00 及之后出发时，仍用默认 8h（入夜规则另计）。
 */
export function computeOutboundPlanHours(
  time: string,
  options: { maxHours?: number; minHours?: number } = {},
): number {
  const maxHours = options.maxHours ?? 8;
  const minHours = options.minHours ?? 2;
  const min = minutesSinceMidnight(normalizeWorldTime(time));
  if (min >= EVENING_CUTOFF_MINUTES) {
    return maxHours;
  }
  const hoursUntilCutoff = (EVENING_CUTOFF_MINUTES - min) / 60;
  return Math.min(maxHours, Math.max(minHours, Math.min(maxHours, hoursUntilCutoff)));
}

/** 18:00–04:59 视为入夜（含黄昏后外出惩罚） */
export function isNightWorldTime(time: string | undefined): boolean {
  if (!time?.trim()) {
    return false;
  }
  const min = minutesSinceMidnight(time);
  return min >= 18 * 60 || min < 5 * 60;
}

/** 05:00–11:59 视为清晨时段 */
export function isMorningWorldTime(time: string | undefined): boolean {
  if (!time?.trim()) {
    return false;
  }
  const min = minutesSinceMidnight(time);
  return min >= 5 * 60 && min < 12 * 60;
}

export function formatWorldTimeDisplay(time: string): string {
  return normalizeWorldTime(time);
}
